-- ==========================================================================================
-- This procedure was automatically generated by Insikt Studio.
-- Any edits can and will be overwritten.
-- ==========================================================================================
create procedure [dbo].[PlanningExport_Resultat_To_SourceSystem]
(
	@PlanningVersionID int = null
	,@ParentEventID int = null
	,@ShowProgress bit = 0
)
as

--
-- Standardvariabler
--

declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount

declare 
	@PlanningExportID int
	,@PlanningExportStatusResultat int
	,@VismaTriggerDisabled bit = 0


begin try
	declare @Message nvarchar(max)
	select @Message = 
		case when @PlanningVersionID is null then 
			'Alla aktiva exporteringsbara planeringsversioner'
		else
			'PlaneringsversionID: ' + cast(@PlanningVersionID as nvarchar(12))
		end
			
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output
			,@EventObject = @ProcName
			,@EventTitle = 'Export av: Resultatplanering -> Visma'
			,@Description = @Message
		
	if @PlanningVersionID is null
			begin				
				select
					@PlanningVersionID = 
						min(pv.PlanningVersionID)						
				from
					dw.dim_PlanningVersion pv
				where
					(pv.IsBudget = 1 or pv.OpenForSuperUsers = 1)
					and (Type = 1 or Attribute3 <> '')
					and isnull(FCVersionCategoryID, 0) <> -1 -- Planeringsversion vars master ligger i Visma får inte skrivas över.
				if @PlanningVersionID is null
					begin
						raiserror('Ingen exporteringsbar planeringsversion är öppen. Ingen planeringsversion exporterades.', 16, 10)
					end

				declare @TempResult int
				while @PlanningVersionID is not null
					begin
						set @TempResult = -1
						begin try
							exec [dbo].[PlanningExport_Resultat_To_SourceSystem]						
								@PlanningVersionID = @PlanningVersionID
						end try
						begin catch
							if @TempResult <> -1
								begin
									set @PlanningExportStatusResultat = 
										case 
											when @TempResult > isnull(@PlanningExportStatusResultat, -1) then @TempResult 
											else @PlanningExportStatusResultat 
										end
								end
							else
								begin
									exec app.ReThrowError
								end
						end catch
						select
							@PlanningVersionID = 
								min(pv.PlanningVersionID)						
						from
							dw.dim_PlanningVersion pv
						where
							(pv.IsBudget = 1 or pv.OpenForSuperUsers = 1)
							and (Type = 1 or Attribute3 <> '')
							and isnull(FCVersionCategoryID, 0) <> -1 -- Planeringsversion vars master ligger i Visma får inte skrivas över.
							and pv.PlanningVersionID > @PlanningVersionID
					end
			end
		else

	declare @Attribute3 int
	set @Attribute3 = (select Attribute3 from [INSIKT_KUND_SYS].[dbo].FCVersion where ID = @planningVersionID) 

	if @Attribute3 is null
		begin
			declare @maxid int
			set @maxid = (select max(bgtno) from [F2222].[dbo].bgt)

			insert into [F2222].[dbo].bgt (BGtNo, Nm, Yr)
			
			select
			@maxid +1
			,Name
			,FiscalYear
			from [INSIKT_KUND_SYS].[dbo].FCVersion
			where ID = @PlanningVersionID
			
			set @Attribute3 = @maxid+1

			update [INSIKT_KUND_SYS].dbo.FCVersion
			set Attribute3 = @Attribute3
			where ID = @PlanningVersionID
		end

	delete
	from
		[F2222].dbo.BgtLn
	where bgNo = @Attribute3

	insert into [F2222].[dbo].BgtLn
	(
		BgNo, LnNo, Dt, Yr, Pr, AcYrPr, AcNo, R1, R2, R3, R4, R5, R6, [DbIncCst], [CrInvoAm]
	)
	select
		fcv.Attribute3
		, LnNo = ROW_NUMBER () over (order by DateID) + 660
		, dtime.DateID
		, dtime.FiscalYear
		, dtime.FiscalPeriod
		, dtime.FiscalYear*100 + dtime.FiscalPeriod
		, Konto.Code
		, isnull([Avdelning].Code, 0)
				, isnull([Projekt].Code, 0)
				, 0
				, isnull([Varugrupp].Code, 0)
				, 0
				, isnull([Kampanj].Code, 0)
				, case when sum(f.PlanningAmount) < 0 then 0 else abs(sum(f.PlanningAmount)) end
		, case when sum(f.PlanningAmount) > 0 then 0 else abs(sum(f.PlanningAmount)) end
	from dw.fact_Resultat_Planning f
		right join [INSIKT_KUND_SYS].[dbo].[FCVersion] fcv on
			f.PlanningVersionID = fcv.ID
		left join [dw].[base_Konto] [Konto] on
			[Konto].KontoID = f.KontoID
		left join dw.dim_time dtime on
			f.PostingDateID = dtime.DateID
		left join [dw].[base_Avdelning] [Avdelning] on
			[Avdelning].[AvdelningID] = f.[AvdelningID]
		left join [dw].[base_Kampanj] [Kampanj] on
			[Kampanj].[KampanjID] = f.[KampanjID]
		left join [dw].[base_Projekt] [Projekt] on
			[Projekt].[ProjektID] = f.[ProjektID]
		left join [dw].[base_Varugrupp] [Varugrupp] on
			[Varugrupp].[VarugruppID] = f.[VarugruppID]
	where
		f.PlanningVersionID = @PlanningVersionID
	group by 
		Attribute3, 
		FiscalPeriod, 
		Konto.Code, 
		[Avdelning].Code,
		[Kampanj].Code,
		[Projekt].Code,
		[Varugrupp].Code,
		dTime.FiscalYear, DateID
 
exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------	
end try
begin catch	
	--
	-- Rulla tillbaka eventualla transaktioner startade i den här procedurn och logga fel.
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran

	
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch
if @PlanningExportStatusResultat <> 1
	begin
		--
		-- Exporten lyckades inte till 100% en eller fler rader exporterades in.
		--
		raiserror('Exporten lyckades inte till 100% en eller fler rader exporterades in.', 11, 1)
	end

GO
